/**
 * POC build: known-good vendor automation scripts, embedded directly (no automate-server
 * fetch). Keyed by hostname of the vendor link. Extend this map to support more vendors.
 */

export const KNOWN_SCRIPTS = {
  "entradas.museodelprado.es": "(function () {\n  function findEl(candidates, stepIndex, action) {\n    for (const sel of candidates) {\n      let el = null;\n      if (sel.startsWith(\"xpath=\")) {\n        el = document.evaluate(sel.slice(6), document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;\n      } else {\n        el = document.querySelector(sel);\n      }\n      if (el) return el;\n    }\n    throw new Error(`Step ${stepIndex} (${action}): no element matched candidates ${JSON.stringify(candidates)}`);\n  }\n\n  // Real gap found 2026-10-07, confirmed live: a plain `el.click()` on the calendar's day\n  // cell does NOT register as a real date selection with the site's own widget (page stays\n  // on \"Please choose a day for your ticket\" even though this script's own `#space-info-*`\n  // presence check -- which only tests DOM existence, not real selection state -- wrongly\n  // reads it as done). Since no date is actually selected server-side, EVERY ticket type's\n  // \"+\" control shows `blockeddate` indefinitely (confirmed: static and unchanging for 35+\n  // real seconds of observation) -- this is not sold-out inventory, not a timing race, and\n  // not anti-bot blocking; it is simply that `.click()` alone doesn't fire whatever the\n  // widget listens for. Dispatching the full native mousedown/mouseup/click sequence (still\n  // entirely scripted, not a real OS input event) fixes it -- confirmed live end-to-end,\n  // including the pax \"+\" stepper afterward. Use this for every click in this script instead\n  // of the bare `.click()` method.\n  function realClick(el) {\n    // Real gap found 2026-10-07, confirmed live: the calendar can leave its day cells\n    // positioned outside the viewport (e.g. mid-transition between its two rendered\n    // months) even while `offsetParent !== null` reports them as \"visible\" -- dispatching\n    // a correctly-sequenced mousedown/mouseup/click still silently failed to register in\n    // that state, and started working again only once scrolled into view first. Always\n    // force the element into view before computing coordinates.\n    el.scrollIntoView({ block: \"center\" });\n    const rect = el.getBoundingClientRect();\n    // No `view: window`: the extension runs this in an isolated (USER_SCRIPT) world where\n    // that is a different global; the page's handlers never read it.\n    const opts = { bubbles: true, cancelable: true, clientX: rect.x + rect.width / 2, clientY: rect.y + rect.height / 2 };\n    el.dispatchEvent(new MouseEvent(\"mousedown\", opts));\n    el.dispatchEvent(new MouseEvent(\"mouseup\", opts));\n    el.dispatchEvent(new MouseEvent(\"click\", opts));\n  }\n\n  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n\n  function setNativeValue(el, value) {\n    // Real gap found 2026-10-08 (RO team testing, live ticket): Aries returned a guest last\n    // name with a trailing space (\"Muck \"), which the vendor form rejects as \"The format is\n    // invalid\". Never type leading/trailing whitespace into a vendor form.\n    const clean = String(value ?? \"\").replace(/\\s+/g, \" \").trim();\n    const proto = Object.getPrototypeOf(el);\n    const setter = Object.getOwnPropertyDescriptor(proto, \"value\")?.set;\n    if (setter) setter.call(el, clean); else el.value = clean;\n    el.dispatchEvent(new Event(\"input\", { bubbles: true }));\n    el.dispatchEvent(new Event(\"change\", { bubbles: true }));\n  }\n\n  // Real gap found 2026-10-08: the site renders in Spanish for fresh/incognito sessions, where\n  // the country option reads \"Estados Unidos\", not \"United States\" -- match on the ISO value too.\n  const COUNTRY_ISO = { \"united states\": \"US\", \"estados unidos\": \"US\" };\n\n  function selectByTextOrValue(el, text) {\n    const options = Array.from(el.options);\n    const norm = (s) => (s || \"\").trim().toLowerCase();\n    const match =\n      options.find((o) => norm(o.textContent) === norm(text)) ||\n      options.find((o) => norm(o.value) === norm(text)) ||\n      options.find((o) => COUNTRY_ISO[norm(text)] && o.value === COUNTRY_ISO[norm(text)]) ||\n      options.find((o) => norm(o.textContent).includes(norm(text)));\n    if (match) el.value = match.value;\n    el.dispatchEvent(new Event(\"change\", { bubbles: true }));\n  }\n\n  function getByPath(obj, path) {\n    return path.split(\".\").reduce((acc, key) => (acc == null ? acc : acc[key]), obj);\n  }\n\n  async function runSteps(booking, ctx) {\n    // Real gap found 2026-09-24 (confirmed live, same architecture as midaticket.com): this\n    // flow spans MULTIPLE real page navigations (ticket-selection page -> possibly an\n    // add-ons page -> checkout/guest-details page, on entradas.museodelprado.es/checkout/).\n    // The outer retry-the-whole-sequence loop (see run() below) is for TRANSIENT same-page\n    // issues, not \"we already navigated past this page\" -- retrying from the top after\n    // reaching checkout would re-run calendar/ticket-type logic on a page that has neither.\n    // Check which page we're actually on FIRST.\n    // Real gap found 2026-09-25: DOM markers alone are unreliable as the FIRST check -- if\n    // the ticket-selection page's calendar widget simply hasn't rendered yet (this script is\n    // re-injected and run essentially immediately after navigation/retry), NEITHER marker\n    // matches yet, and the old logic fell through to bridgeToCheckout() -- which does nothing\n    // useful on the ticket page (its buttons don't exist there either) and then still fell\n    // through into runCheckoutFormSteps(), failing immediately since the email field can never\n    // appear on a page that was never navigated to checkout. Confirmed live via DEBUG payload:\n    // url stayed at the site root with ticket-selection-page-only input names (qty/spaces).\n    // The URL PATH is a far more reliable primary signal than transient DOM state -- checkout\n    // lives at a distinct `/checkout/` path; anything else on this domain is the ticket-\n    // selection flow (which already has its own internal poll for the calendar to render).\n    //\n    // Real gap found 2026-10-07: a loose `pathname.includes(\"/checkout\")` ALSO matches the\n    // add-ons page (`/checkout/cart/`), not just the real guest-details form\n    // (`/checkout/` exactly) -- confirmed live, landing on `/checkout/cart/` mid-run. That\n    // made this dispatcher wrongly treat the add-ons page as \"already at the final form\",\n    // skipping straight to runCheckoutFormSteps() (which then just polls for the email field\n    // for 20s, fails, and the outer retry loop retries the SAME wrong branch every time --\n    // never calling bridgeToCheckout() to click through the add-ons page, since that only\n    // happens inside runTicketSelectionSteps()'s own tail). Match the guest-details page's\n    // path EXACTLY (optionally with a trailing slash/query), and treat anything else under\n    // `/checkout/*` as an intermediate page to bridge through -- same helper\n    // runTicketSelectionSteps() already uses at its own tail, just reachable from here too now.\n    // Real gap found 2026-10-08 (RO team, two live tickets stuck on the add-ons page): the add-ons\n    // page (/checkout/cart/) ALSO contains a hidden login form with `[name=\"username\"]`\n    // (#customer-email), so using that field -- or #data_prot -- as the \"I'm on the guest-details\n    // form\" marker made this script think it had already arrived, skip clicking Continue, and\n    // then fail on the missing confirm-email field. `usernameConfirm` exists only on the real\n    // guest-details form.\n    const onGuestDetailsPage = /^\\/checkout\\/?(?:[?#]|$)/.test(location.pathname) || !!document.querySelector('[name=\"usernameConfirm\"]');\n    const onTicketPage = !onGuestDetailsPage && !location.pathname.includes(\"/checkout\");\n\n    if (onTicketPage) {\n      await runTicketSelectionSteps(booking);\n    } else if (!onGuestDetailsPage) {\n      await bridgeToCheckout();\n    }\n\n    await runCheckoutFormSteps(booking);\n    return { status: \"PAYMENT_REQUIRED\" };\n  }\n\n  // Real gap found 2026-09-24: an intermediate page (add-ons, or a brief transition) between\n  // ticket selection and checkout may need its own \"continue\" click -- poll for the checkout\n  // form to appear, clicking whichever known continue control is present each time.\n  async function bridgeToCheckout() {\n    // Real gap found 2026-10-08 (RO team, two live tickets stuck on the add-ons page): this\n    // used to re-click the continue button every 0.5-1.5s while waiting for the page to\n    // navigate. The click starts a request and a page transition; every extra click while\n    // that is in flight re-submits it, and the page ends up wedged on the add-ons page\n    // (the exact same click made once, with nothing else going on, navigates immediately).\n    // Click ONCE, then give the transition a long window to complete before trying again.\n    const FORM = '[name=\"usernameConfirm\"]';\n    const overall = Date.now() + 150000;\n    while (Date.now() < overall && !document.querySelector(FORM)) {\n      const btn = document.querySelector(\"#checkoutComplements, #checkoutSummary\");\n      if (btn && !btn.disabled && !btn.classList.contains(\"disabled\")) {\n        realClick(btn);\n        const settle = Date.now() + 45000; // the vendor can take 60s+ on a slow day; a second click mid-request double-submits\n        while (Date.now() < settle && !document.querySelector(FORM)) await sleep(300);\n      } else {\n        await sleep(500);\n      }\n    }\n  }\n\n  async function runTicketSelectionSteps(booking) {\n    // Step 0: dismiss the cookie-consent banner if shown -- confirmed non-deterministic\n    // (present or not depending on session/geo). Real gap found 2026-10-07: the site has\n    // switched cookie-consent providers since this script was first written -- it no longer\n    // uses OneTrust (#onetrust-accept-btn-handler, which no longer exists on the page at\n    // all, confirmed live) but a different plugin, \"Cookie Law Advice\"\n    // (#cookie_law_advice_close / .cookie-law-advice-close, confirmed live). Keep the old\n    // selector as a last-resort fallback in case the site reverts, but the current one must\n    // come first.\n    try {\n      const el0 = findEl([\"#cookie_law_advice_close\", \".cookie-law-advice-close\", \"#onetrust-accept-btn-handler\"], 0, \"click\");\n      realClick(el0);\n    } catch (e) {\n      // Banner not present this run -- optional step, not a failure.\n    }\n\n    // Step 1 (intentionally skipped): do NOT switch the site to English. Real gap found\n    // 2026-09-24, three rounds: (a) a raw synthetic .click() on the Magento store-switcher\n    // link (a `data-post` control, no plain href) fell through to its bare `href=\"#\"`\n    // instead of triggering Magento's own JS handler; (b) navigating directly to\n    // `?___store=en` worked as a fresh first navigation but not reliably mid-session; (c)\n    // replicating Magento's real mechanism exactly -- reading `data-post` and submitting a\n    // real form POST to `/stores/store/redirect/`, the way `mage/common.js` does -- got a\n    // clean, direct 403 from Cloudflare specifically on that endpoint (confirmed via a raw\n    // fetch: `server: cloudflare`, no redirect chain at all), the same automation\n    // fingerprinting found elsewhere this session, this time on a different endpoint. Since\n    // this is Cloudflare blocking OUR harness's request rather than anything about how the\n    // request is constructed, no client-side mechanism fixes it. Instead of requiring\n    // English, every selector below that used to depend on English text has been rewritten\n    // to work directly against the site's default Spanish content (confirmed live): the\n    // destination radios were already language-agnostic (`for=\"space-48\"/\"space-49\"`); the\n    // English \"General + Exhibition time pass\" ticket name is \"General + Pase Exposici\u00f3n\" in\n    // Spanish (confirmed live), and plain \"General\" is spelled identically in both languages.\n\n    // Step 2: navigate the (possibly dual-month) calendar to the booking's target month/\n    // year, then click the day. Real gap found 2026-09-24: this used to match the target\n    // month by comparing \".ui-datepicker-title\" TEXT against English month names -- broken\n    // once the language switch was dropped (Step 1), since that title renders in Spanish\n    // (\"octubre 2026\", not \"October 2026\") and would never match. Each day cell's own\n    // `data-month`/`data-year` attributes (0-indexed month, matching JS's own\n    // `Date.getMonth()`) are language-agnostic -- match on those directly instead.\n    const inventoryDate = getByPath(booking, \"inventoryDate\");\n    const targetDateObj = new Date(inventoryDate + \"T00:00:00Z\");\n    const targetMonth0 = targetDateObj.getUTCMonth();\n    const targetYear = targetDateObj.getUTCFullYear();\n    const targetDay = targetDateObj.getUTCDate();\n\n    function findTargetDay() {\n      return document.querySelector(\n        `td[data-handler=\"selectDay\"][data-month=\"${targetMonth0}\"][data-year=\"${targetYear}\"] a[data-date=\"${targetDay}\"]`\n      );\n    }\n\n    // Real gap found 2026-09-25: this whole function can now re-run from scratch on a\n    // same-page retry (see runSteps()). If a PREVIOUS partial run already picked the date, the\n    // calendar widget is gone from the DOM (replaced by the ticket-type panel) -- polling for\n    // it here would just burn the full 8s timeout and then fail Step 2 outright, even though\n    // the date step is actually already done. Skip straight past date selection when the\n    // ticket-type panel is already showing.\n    // Real gap found 2026-10-07, confirmed live: `#space-info-48`/`#space-info-49` are\n    // ALWAYS present in the DOM from first page load, just carrying a `hidden` class until\n    // a date is genuinely picked -- checking for their bare existence (as this used to)\n    // was true on every fresh page, so this whole date-selection block was silently\n    // skipped on literally every automated run, every time, and the script proceeded\n    // straight to Step 3 having never actually selected a date -- which is the REAL root\n    // cause behind every `blockeddate` failure seen in this script's history (a fresh page\n    // has no date selected server-side, so every single ticket type's \"+\" control is\n    // blocked, not just the one this script happened to target). Confirmed live: after a\n    // real selection, the active panel loses its `hidden` class while the other keeps it --\n    // check for that instead of bare presence.\n    const dateAlreadyPicked = !!document.querySelector(\"#space-info-48:not(.hidden), #space-info-49:not(.hidden)\");\n    if (!dateAlreadyPicked) {\n    // Real gap found 2026-09-24: checking for the \"Next\" control ONCE and treating a null\n    // result as \"no more months, stop\" is wrong on a freshly-loaded page -- the widget may\n    // simply not have rendered yet (this script gets re-injected and run essentially\n    // immediately after navigation). Poll for the widget to exist at all first, and give a\n    // short grace period before accepting an absent \"Next\" control as final.\n    const widgetDeadline = Date.now() + 8000;\n    while (Date.now() < widgetDeadline && !document.querySelector(\".ui-datepicker-next, td[data-handler=\\\"selectDay\\\"]\")) {\n      await new Promise((r) => setTimeout(r, 250));\n    }\n\n    const navLog = [];\n    let iterations = 0;\n    for (let i = 0; i < 24 && !findTargetDay(); i++) {\n      iterations = i + 1;\n      let nextBtn = document.querySelector(\".ui-datepicker-next:not(.ui-state-disabled)\");\n      if (!nextBtn) {\n        const graceDeadline = Date.now() + 1500;\n        while (Date.now() < graceDeadline && !nextBtn) {\n          await new Promise((r) => setTimeout(r, 200));\n          nextBtn = document.querySelector(\".ui-datepicker-next:not(.ui-state-disabled)\");\n        }\n      }\n      if (!nextBtn) {\n        navLog.push(`i=${i}: no next button`);\n        break;\n      }\n      realClick(nextBtn);\n      const clickDeadline = Date.now() + 2500;\n      while (Date.now() < clickDeadline) {\n        await new Promise((r) => setTimeout(r, 300));\n        if (findTargetDay()) break;\n      }\n      const titles = Array.from(document.querySelectorAll(\".ui-datepicker-title\")).map((t) => t.textContent.trim());\n      navLog.push(`i=${i}: clicked, titles=${JSON.stringify(titles)}`);\n    }\n    const dayEl = findTargetDay();\n    if (!dayEl) {\n      const groupCount = document.querySelectorAll(\".ui-datepicker-group\").length;\n      const widgetPresent = !!document.querySelector(\".ui-datepicker-next, td[data-handler=\\\"selectDay\\\"]\");\n      const anyDataMonth = document.querySelectorAll(\"[data-month]\").length;\n      const bodyLen = document.body.innerHTML.length;\n      throw new Error(\n        \"Step 2 (click): no element matched candidates [\\\"calendar day for target month/year\\\"] DEBUG \" +\n          JSON.stringify({ iterations, navLog, groupCount, widgetPresent, anyDataMonth, bodyLen, url: location.href, targetMonth0, targetYear, targetDay })\n      );\n    }\n    realClick(dayEl);\n    await new Promise((r) => setTimeout(r, 2000));\n    }\n\n    // Ticket names differ by site language: \"General + Pase Exposici\u00f3n\" (es) vs\n    // \"General + Exhibitions time pass\" (en). Plain \"General\" is the same in both, and the\n    // Spanish site ALSO lists \"General + Libro ...\" in the same panel, which must not match.\n    const IS_GENERAL_PLUS_EXHIBITION = /^General\\s*\\+\\s*(Pase\\s*Exposici|Exhibition)/i;\n    const IS_PLAIN_GENERAL = /^General$/i;\n\n    // Step 3: select ticket destination/type -- try \"Collection + Exhibitions\" /\n    // \"General + Pase Exposici\u00f3n\" first; if that ticket row is unavailable/disabled,\n    // fall back to plain \"Collection\" / \"General\" (same fallback rule as the vendor's own\n    // booking instructions). Whichever is usable, click its \"+\" quantity control once per\n    // pax and wait for the input to reflect the running count each time.\n    let spaceId = \"space-info-48\";\n    const expLabel = document.querySelector('label:not(.space-description)[for=\"space-49\"]');\n    if (expLabel && expLabel.offsetParent !== null) {\n      realClick(expLabel);\n      // Poll rather than a single fixed wait -- this panel's real render timing has proven\n      // variable elsewhere in this same flow (the calendar needed the same treatment).\n      const panelDeadline = Date.now() + 5000;\n      while (Date.now() < panelDeadline && document.querySelectorAll(\"#space-info-49 .ticket-name\").length === 0) {\n        await new Promise((r) => setTimeout(r, 300));\n      }\n      const wrapper49 = Array.from(document.querySelectorAll(\"#space-info-49 .ticket-name\"))\n        .find((el) => IS_GENERAL_PLUS_EXHIBITION.test((el.textContent || \"\").trim()))\n        ?.closest(\".wrapper-ticket-info\");\n      const row49 = wrapper49?.closest(\"li.row\");\n      const add49 = wrapper49?.querySelector(\"a.add:not(.disabled)\");\n      const usable49 = !!wrapper49 && !!add49 && !row49?.classList.contains(\"unavailable\");\n      if (usable49) {\n        spaceId = \"space-info-49\";\n      } else {\n        const collectionLabel = document.querySelector('label:not(.space-description)[for=\"space-48\"]');\n        if (collectionLabel) realClick(collectionLabel);\n        await new Promise((r) => setTimeout(r, 1000));\n      }\n    }\n    const ticketNameMatches = spaceId === \"space-info-49\" ? IS_GENERAL_PLUS_EXHIBITION : IS_PLAIN_GENERAL;\n    const wrapper = Array.from(document.querySelectorAll(`#${spaceId} .ticket-name`))\n      .find((el) => ticketNameMatches.test((el.textContent || \"\").trim()))\n      ?.closest(\".wrapper-ticket-info\");\n    const qtyInput = wrapper?.querySelector(\"input.qty\");\n    if (!qtyInput || !qtyInput.id) {\n      throw new Error(\"Step 3 (click): no element matched candidates [\\\"ticket quantity input\\\"]\");\n    }\n    const totalPax = getByPath(booking, \"totalPax\") || 1;\n    // Real gap found 2026-09-25: with the dispatcher now able to re-run this whole function\n    // from scratch on any same-page retry (see runSteps() above), blindly clicking \"+\" from\n    // target=1 every time would double-add pax on a retry that already made partial progress.\n    // Start from whatever quantity is ALREADY showing, not from 0.\n    const startQty = parseInt(document.getElementById(qtyInput.id)?.value || \"0\", 10) || 0;\n    const addXpath = `xpath=//*[@id=\"${qtyInput.id}\"]/ancestor::div[contains(@class,\"wrapper-ticket-info\")]//a[contains(@class,\"add\") and not(contains(@class,\"disabled\"))]`;\n    for (let target = startQty + 1; target <= totalPax; target++) {\n      // Real gap found 2026-09-25: right after a click, Prado's own AJAX call to update the\n      // cart adds a `disabledLink` class to this SAME \"+\" anchor for ~1.3s (confirmed live)\n      // before removing it again once the request resolves -- a plain one-shot findEl() can\n      // fire in that exact window (e.g. right after the previous iteration's qty-value poll\n      // exits) and throw immediately with no chance to recover. Poll for the enabled button\n      // specifically, not just a single point-in-time check.\n      //\n      // Real gap found 2026-09-25, second round: on a genuinely FRESH page load (this\n      // script's own first pass through Step 3, right after selecting the date), the SAME\n      // anchor can carry a `blockeddate` class for longer than the ~1.3s post-click case --\n      // confirmed live: a manual replay of this exact flow (date select -> destination\n      // fallback -> qty check) against the SAME real date, with more natural wall-clock time\n      // between steps, found the ticket genuinely available (`class=\"add\"`, not blocked) --\n      // proving this is Prado's own per-day availability check still resolving on a cold\n      // load, not real sold-out inventory. Give it real room to resolve.\n      const enabledDeadline = Date.now() + 20000;\n      let el3 = document.evaluate(addXpath.slice(6), document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;\n      while (!el3 && Date.now() < enabledDeadline) {\n        await new Promise((r) => setTimeout(r, 200));\n        el3 = document.evaluate(addXpath.slice(6), document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;\n      }\n      if (!el3) {\n        const rawAnchor = document.querySelector(`#${qtyInput.id}`)?.closest(\".wrapper-ticket-info\")?.querySelector(\"a.add, a[data-bind='click: increaseQty']\");\n        throw new Error(\n          `Step 3 (click): no element matched candidates [\"${addXpath}\"] DEBUG ` +\n            JSON.stringify({\n              target,\n              startQty,\n              qtyNow: document.getElementById(qtyInput.id)?.value,\n              rawAnchorClass: rawAnchor?.className,\n              rawAnchorOuter: rawAnchor?.outerHTML,\n              wrapperFound: !!document.querySelector(`#${qtyInput.id}`)?.closest(\".wrapper-ticket-info\"),\n            })\n        );\n      }\n      realClick(el3);\n      const deadline = Date.now() + 12000;\n      while (Date.now() < deadline && document.getElementById(qtyInput.id)?.value !== String(target)) {\n        await new Promise((r) => setTimeout(r, 250));\n      }\n    }\n\n    // Step 4: choose the visit time. Real gaps found 2026-10-08 (RO team, live tickets):\n    //  (a) this used to take the FIRST available slot, not the booking's requested time -- two\n    //      live Prado bookings (asked 16:30 / 17:30) were booked for 11:15 / 14:30;\n    //  (b) it found the \"Set Hour\" button by scanning for any leaf element whose text matched\n    //      /hora/ -- in Spanish (fresh/incognito sessions) the section heading \"ELIJA SU HORA\n    //      DE VISITA\" matches first and the button is labelled \"Elegir hora\", so the picker\n    //      never opened and the run stalled right after the pax step.\n    // The button is `button.selector[data-expo]` and each slot is a button inside\n    // `.time-wrapper-container` with `span.hour` (\"16:30\") and `span.aforo` (remaining\n    // capacity; sold-out slots carry class \"disabled\") -- none of it language dependent.\n    const toMinutes = (t) => {\n      const m = /(\\d{1,2}):(\\d{2})/.exec(String(t ?? \"\"));\n      return m ? Number(m[1]) * 60 + Number(m[2]) : null;\n    };\n    const targetMinutes = toMinutes(getByPath(booking, \"inventoryTime\"));\n    const hhmm = (mins) => `${String(Math.floor(mins / 60)).padStart(2, \"0\")}:${String(mins % 60).padStart(2, \"0\")}`;\n    // Vendor-approved tolerance from the ticket's booking instructions: tickets may be for up\n    // to 45 minutes EARLIER than the requested time if that exact slot is sold out.\n    const MAX_EARLIER_MINUTES = 45;\n\n    const visibleHourButtons = () => Array.from(document.querySelectorAll(\"button.selector[data-expo]\")).filter((b) => b.offsetParent !== null);\n    const openSlots = () =>\n      Array.from(document.querySelectorAll(\".time-wrapper-container button\"))\n        .filter((b) => b.offsetParent !== null && !b.classList.contains(\"disabled\"))\n        .map((b) => ({\n          el: b,\n          minutes: toMinutes(b.querySelector(\".hour\")?.textContent),\n          capacity: parseInt(b.querySelector(\".aforo\")?.textContent ?? \"\", 10),\n        }))\n        .filter((s) => s.minutes !== null && (Number.isNaN(s.capacity) || s.capacity >= totalPax));\n\n    for (const hourBtn of visibleHourButtons()) {\n      // Already set by an earlier pass of this function (same-page retry): leave it alone.\n      if (targetMinutes !== null && Array.from(document.querySelectorAll(\".exhibition-hour\")).some((e) => e.offsetParent !== null && e.textContent.includes(hhmm(targetMinutes)))) continue;\n      // Open the picker. Retry the click only if it hasn't opened -- not on a tight loop.\n      const modalDeadline = Date.now() + 15000;\n      let slots = [];\n      while (Date.now() < modalDeadline && slots.length === 0) {\n        realClick(hourBtn);\n        // The picker can take a few seconds to render; clicking again while it is loading\n        // TOGGLES it closed, so give each click a long window before retrying.\n        const wait = Date.now() + 6000;\n        while (Date.now() < wait && slots.length === 0) {\n          await sleep(250);\n          slots = openSlots();\n        }\n      }\n      if (slots.length === 0) {\n        throw new Error(\"Step 4 (click): no element matched candidates [\\\"open time slot for \" + totalPax + \" pax\\\"]\");\n      }\n\n      let chosen;\n      if (targetMinutes === null) {\n        chosen = slots[0];\n      } else {\n        chosen =\n          slots.find((s) => s.minutes === targetMinutes) ??\n          slots\n            .filter((s) => s.minutes < targetMinutes && targetMinutes - s.minutes <= MAX_EARLIER_MINUTES)\n            .sort((x, y) => y.minutes - x.minutes)[0];\n      }\n      if (!chosen) {\n        // Deliberately NOT a \"no element matched\" error: the outer retry loop must not spin on\n        // this, and it must never fall back to an unrelated slot (that is the bug being fixed).\n        throw new Error(\n          `Requested time ${hhmm(targetMinutes)} is not available for ${totalPax} pax (and nothing within ${MAX_EARLIER_MINUTES} min before it). Open slots: ${slots.map((s) => hhmm(s.minutes)).join(\", \")}`\n        );\n      }\n\n      realClick(chosen.el);\n      // The slot is applied by an AJAX call (spinner) that can take several seconds: wait for\n      // the page to show the chosen time and for Continue to enable, instead of a fixed pause.\n      const chosenText = hhmm(chosen.minutes);\n      const applyDeadline = Date.now() + 25000;\n      let applied = false;\n      while (Date.now() < applyDeadline) {\n        const shown = Array.from(document.querySelectorAll(\".exhibition-hour\")).some((e) => e.offsetParent !== null && e.textContent.includes(chosenText));\n        const modalClosed = !Array.from(document.querySelectorAll(\".time-wrapper-container\")).some((w) => w.offsetParent !== null);\n        if (shown && modalClosed) { applied = true; break; }\n        await sleep(300);\n      }\n      if (!applied) {\n        throw new Error(`Time ${chosenText} was clicked but the page never confirmed it`);\n      }\n    }\n\n    // Step 5: proceed past ticket selection. Continue stays disabled until the slot has been\n    // applied; wait for it, then click ONCE (see bridgeToCheckout() for why not repeatedly).\n    const continueDeadline = Date.now() + 25000;\n    while (Date.now() < continueDeadline) {\n      const c = document.querySelector(\"#checkoutSummary\");\n      if (c && !c.disabled && !c.classList.contains(\"disabled\")) break;\n      await sleep(300);\n    }\n    await bridgeToCheckout();\n  }\n\n  async function runCheckoutFormSteps(booking) {\n    // Real gap found 2026-09-24: this checkout page is a Magento 2 Knockout.js checkout --\n    // its sections render asynchronously and NOT all at once, confirmed live: `#data_prot`\n    // (the privacy checkbox, used as one of the \"we've reached checkout\" markers) can be\n    // present in the DOM before `[name=\"username\"]` (the email field) has rendered yet.\n    // Poll for the actual field this function needs first, rather than trusting the\n    // dispatcher's more general page-level check alone.\n    const emailFieldDeadline = Date.now() + 20000;\n    const formReady = () => !!document.querySelector('[name=\"username\"]') && !!document.querySelector('[name=\"usernameConfirm\"]');\n    while (Date.now() < emailFieldDeadline && !formReady()) {\n      await new Promise((r) => setTimeout(r, 300));\n    }\n    if (!formReady()) {\n      throw new Error(\n        \"Step 7 (fill): no element matched candidates [\\\"[name=\\\\\\\"usernameConfirm\\\\\\\"]\\\"] DEBUG \" +\n          JSON.stringify({\n            title: document.title,\n            url: location.href,\n            bodyLen: document.body.innerHTML.length,\n            loadingMask: !!document.querySelector(\".loading-mask, ._block-content-loading\"),\n            hasDataProt: !!document.querySelector(\"#data_prot\"),\n            hasOpcWrapper: !!document.querySelector(\".opc-wrapper, .checkout-container\"),\n            inputNames: Array.from(document.querySelectorAll(\"input\")).map((el) => el.name || el.id).slice(0, 30),\n          })\n      );\n    }\n\n    // Step 7: fill email + confirm email.\n    const el7 = findEl(['[name=\"username\"]'], 7, \"fill\");\n    setNativeValue(el7, getByPath(booking, \"guestDetails.email\"));\n    const el7b = findEl(['[name=\"usernameConfirm\"]'], 7, \"fill\");\n    setNativeValue(el7b, getByPath(booking, \"guestDetails.email\"));\n\n    // Step 8: fill full name (Prado's checkout form uses ONE combined name field).\n    const el8 = findEl(['[name=\"firstname\"]'], 8, \"fill\");\n    setNativeValue(el8, `${getByPath(booking, \"guestDetails.firstName\")} ${getByPath(booking, \"guestDetails.lastName\")}`);\n\n    // Step 9: fill address line, postal code, country.\n    const el9 = findEl(['[name=\"street[0]\"]'], 9, \"fill\");\n    setNativeValue(el9, getByPath(booking, \"guestDetails.address.line1\"));\n    const el9b = findEl(['[name=\"postcode\"]'], 9, \"fill\");\n    setNativeValue(el9b, getByPath(booking, \"guestDetails.address.postalCode\"));\n    const el9c = findEl(['[name=\"country_id\"]'], 9, \"select\");\n    selectByTextOrValue(el9c, getByPath(booking, \"guestDetails.address.country\"));\n    await new Promise((r) => setTimeout(r, 900));\n\n    // Step 10: fill region/city/phone -- region may render as a free-text field or a\n    // dropdown depending on the selected country; handle either.\n    const regionText = document.querySelector('[name=\"region\"]');\n    if (regionText && regionText.offsetParent !== null) {\n      setNativeValue(regionText, getByPath(booking, \"guestDetails.address.city\"));\n    }\n    const regionSelect = document.querySelector('[name=\"region_id\"]');\n    if (regionSelect && regionSelect.offsetParent !== null) {\n      selectByTextOrValue(regionSelect, getByPath(booking, \"guestDetails.address.city\"));\n    }\n    const el10 = findEl(['[name=\"city\"]'], 10, \"fill\");\n    setNativeValue(el10, getByPath(booking, \"guestDetails.address.city\"));\n    const el10b = findEl(['[name=\"telephone\"]'], 10, \"fill\");\n    setNativeValue(el10b, getByPath(booking, \"guestDetails.phone\") || \"\");\n    el10b.dispatchEvent(new KeyboardEvent(\"keydown\", { key: \"Tab\", bubbles: true }));\n    await new Promise((r) => setTimeout(r, 3000));\n\n    // Step 11: accept the privacy/data-protection checkbox if present and enabled.\n    const privacy = document.querySelector(\"#data_prot\");\n    if (privacy && !privacy.disabled && !privacy.checked) {\n      const checkmark = document.querySelector('label[for=\"data_prot\"] .checkmark');\n      if (checkmark) {\n        realClick(checkmark);\n        await new Promise((r) => setTimeout(r, 1500));\n      }\n    }\n\n    // Step 12: proceed to payment. Prado's payment form (Realex Payments) is embedded on\n    // this SAME page/domain (confirmed: URL stays on entradas.museodelprado.es/checkout/),\n    // not a cross-origin redirect, so it's safe to click and then stop within this same\n    // invocation -- never enter card details.\n    const el12 = findEl([\"#continuetopayment\"], 12, \"click\");\n    realClick(el12);\n    await new Promise((r) => setTimeout(r, 6000));\n  }\n\n  window.HeadoutAutomation = {\n    async run(booking, ctx) {\n      // Injection can land while the (new) document is still loading; acting on a half-loaded\n      // page is what makes the first clicks of a step silently do nothing.\n      const readyDeadline = Date.now() + 15000;\n      while (document.readyState !== \"complete\" && Date.now() < readyDeadline) await sleep(200);\n      // This flow is long (calendar, ticket-type fallback logic, pax stepper, time-slot\n      // confirm/close, add-ons skip, a multi-field checkout form, and finally the payment\n      // click) -- a single clean pass can easily take 20-30+ seconds, so the retry budget\n      // needs to be sized for that, not for a quick form-fill.\n      const deadline = Date.now() + 65000;\n      while (true) {\n        try {\n          return await runSteps(booking, ctx);\n        } catch (e) {\n          const message = e && e.message ? e.message : String(e);\n          const isMissingElement = /^Step \\d+ \\(\\w+\\): no element matched candidates/.test(message);\n          if (!isMissingElement || Date.now() >= deadline) {\n            return { status: \"ERROR\", error: message };\n          }\n          await new Promise((r) => setTimeout(r, 200));\n        }\n      }\n    },\n  };\n})();\n",
  "vive.midaticket.com": "(function () {\n  function findEl(candidates, stepIndex, action) {\n    for (const sel of candidates) {\n      let el = null;\n      if (sel.startsWith(\"xpath=\")) {\n        el = document.evaluate(sel.slice(6), document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;\n      } else {\n        el = document.querySelector(sel);\n      }\n      if (el) return el;\n    }\n    throw new Error(`Step ${stepIndex} (${action}): no element matched candidates ${JSON.stringify(candidates)}`);\n  }\n\n  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n\n  function setNativeValue(el, value) {\n    // Real gap found 2026-10-08 (RO team, live ticket): Aries returned the guest's last name\n    // as \"Muck \" (trailing space) and this form rejects it (\"The format is invalid\"). Never\n    // type leading/trailing whitespace into a vendor form.\n    const clean = String(value ?? \"\").replace(/\\s+/g, \" \").trim();\n    const proto = Object.getPrototypeOf(el);\n    const setter = Object.getOwnPropertyDescriptor(proto, \"value\")?.set;\n    if (setter) setter.call(el, clean); else el.value = clean;\n    el.dispatchEvent(new Event(\"input\", { bubbles: true }));\n    el.dispatchEvent(new Event(\"change\", { bubbles: true }));\n  }\n\n  function getByPath(obj, path) {\n    return path.split(\".\").reduce((acc, key) => (acc == null ? acc : acc[key]), obj);\n  }\n\n  const MONTHS0 = 0; // getMonth() is already 0-indexed, matching data-month\n\n  async function runSteps(booking, ctx) {\n    // Real gap found 2026-09-24: this flow spans MULTIPLE real page navigations (event page\n    // -> possibly an interim cart page -> checkout page). The outer retry-the-whole-sequence\n    // loop (see run() below) is designed for TRANSIENT same-page issues (an element not\n    // rendered yet), not for \"we've already navigated past this page\" -- confirmed live: an\n    // early attempt got all the way to clicking \"Go to Payment\" and landing on\n    // /en/cart/ or /en/checkout/, a LATER step then failed, and retrying from the top\n    // re-ran the calendar step on a page that no longer has a calendar at all, which can\n    // never succeed. Check which page we're actually on FIRST and skip straight to the\n    // right section -- the checkout form is a reliable, unambiguous marker for \"already past\n    // ticket selection,\" regardless of exactly which page navigations got us there.\n    //\n    // Real gap found 2026-09-24, second round: checking ONLY \"on checkout\" vs \"not on\n    // checkout\" was still wrong -- re-injected on the intermediate /cart/ page (neither the\n    // event page nor checkout), \"not on checkout\" incorrectly ran the calendar-navigation\n    // steps again, which fail immediately since /cart/ has no calendar either. Add a THIRD\n    // state: an event-page marker (the calendar/date-picker widget) that only exists on the\n    // ORIGINAL page -- if we're on neither checkout NOR the event page, treat it as an\n    // in-between page and just look for the same \"proceed\" control to click through.\n    const onCheckoutPage = !!document.querySelector(\"#checkout_last_name, #checkout_first_name\");\n    const onEventPage = !onCheckoutPage && !!document.querySelector(\".ui-datepicker-next, td[data-handler=\\\"selectDay\\\"], .abc-datepicker\");\n\n    if (onEventPage) {\n      // Step 0: dismiss the cookie-consent banner if shown -- confirmed non-deterministic\n      // (may or may not appear), so this is optional/best-effort, not a hard requirement.\n      try {\n        const el0 = findEl([\"button.cky-btn-accept\", \".cky-btn.cky-btn-accept\"], 0, \"click\");\n        el0.click();\n      } catch (e) {\n        // Banner not present this run -- optional step, not a failure.\n      }\n\n      await runTicketSelectionSteps(booking);\n    } else if (!onCheckoutPage) {\n      await bridgeToCheckout();\n    }\n\n    // Steps 5-9 always run once we reach (or already are on) the checkout page -- whether\n    // that took one click or a couple, by this point we're definitely here.\n    await runCheckoutFormSteps(booking);\n\n    // Stop here: everything is filled in and the \"Confirm your reservation\" button is the\n    // next available action, which navigates to a real third-party payment page (Nexi) on a\n    // DIFFERENT origin -- reaching that state (form complete, ready to proceed) is success.\n    // Deliberately not clicking it: a cross-origin navigation would tear down this script's\n    // execution context before it could return, and the extension would not be able to\n    // re-inject on Nexi's own domain to report success cleanly either way.\n    return { status: \"PAYMENT_REQUIRED\" };\n  }\n\n  // Real gap found 2026-09-24: an intermediate page (e.g. /cart/) between ticket selection\n  // and checkout re-uses the SAME \"buy-button\"-shaped proceed control -- poll for the\n  // checkout form to appear, clicking that control again each time it's found, the same\n  // pattern already used at the end of the event-page flow (Step 4) for this exact\n  // uncertainty.\n  async function bridgeToCheckout() {\n    // Click ONCE, then wait. This used to re-click the buy button every 400ms while waiting for\n    // the page to navigate; every extra click re-submits the add-to-cart/continue request and\n    // the cart ends up changed or emptied (RO team, live ticket 2026-10-08: checkout page with\n    // an empty Summary and \"The cart content is changed, check it before proceeding\").\n    const overall = Date.now() + 120000;\n    while (Date.now() < overall && !document.querySelector(\"#checkout_last_name, #checkout_first_name\")) {\n      const btn = document.querySelector(\"#buy-button.payment-button, a#buy-button, button#buy-button\");\n      if (btn) {\n        btn.click();\n        const settle = Date.now() + 40000;\n        while (Date.now() < settle && !document.querySelector(\"#checkout_last_name, #checkout_first_name\")) await sleep(300);\n      } else {\n        await sleep(500);\n      }\n    }\n  }\n\n  async function runTicketSelectionSteps(booking) {\n    // Step 1: navigate the calendar to the booking's target month/year, then select the day.\n    // Ground truth for this selector shape (data-handler/data-month/data-year/data-date) and\n    // the bounded \"click Next until the target month is shown\" pattern comes from a verified,\n    // real, successful Prometheus/Firecrawl run of this exact flow (2026-09-24) -- not guessed.\n    const inventoryDate = getByPath(booking, \"inventoryDate\");\n    const targetDateObj = new Date(inventoryDate + \"T00:00:00Z\");\n    const targetMonth0 = targetDateObj.getUTCMonth();\n    const targetYear = targetDateObj.getUTCFullYear();\n    const targetDay = targetDateObj.getUTCDate();\n\n    // Real gap found 2026-09-24, two rounds: (a) this calendar's month transition is\n    // genuinely slow and variable (confirmed live: sometimes ~600ms is enough, sometimes\n    // 1100ms was still too short) -- poll repeatedly after each click instead of a single\n    // fixed wait. (b) The widget itself may not have rendered AT ALL yet on a fresh page\n    // load -- confirmed the audit harness re-injects this script and calls run() essentially\n    // immediately after navigation, before the calendar's own async init has necessarily\n    // finished, so checking for the \"Next\" control ONCE and treating a null result as \"no\n    // more months, stop\" is wrong here: it can just as easily mean \"not rendered yet.\"\n    // Poll for the widget to exist at all before ever concluding there's nothing to click.\n    const widgetDeadline = Date.now() + 8000;\n    while (Date.now() < widgetDeadline && !document.querySelector(\".ui-datepicker-next, td[data-handler=\\\"selectDay\\\"]\")) {\n      await new Promise((r) => setTimeout(r, 250));\n    }\n\n    const navLog = [];\n    let iterations = 0;\n    for (let i = 0; i < 24; i++) {\n      iterations = i + 1;\n      const dayCell = document.querySelector(\n        `td[data-handler=\"selectDay\"][data-month=\"${targetMonth0}\"][data-year=\"${targetYear}\"] a[data-date=\"${targetDay}\"]`\n      );\n      if (dayCell) break;\n      let nextBtn = document.querySelector(\"a.ui-datepicker-next:not(.ui-state-disabled)\");\n      if (!nextBtn) {\n        // Could genuinely be the end of the calendar, or the widget re-rendering between\n        // months -- give it a short grace period before accepting that as final.\n        const graceDeadline = Date.now() + 1500;\n        while (Date.now() < graceDeadline && !nextBtn) {\n          await new Promise((r) => setTimeout(r, 200));\n          nextBtn = document.querySelector(\"a.ui-datepicker-next:not(.ui-state-disabled)\");\n        }\n      }\n      if (!nextBtn) {\n        navLog.push(`i=${i}: no next button`);\n        break;\n      }\n      nextBtn.click();\n      const clickDeadline = Date.now() + 2500;\n      while (Date.now() < clickDeadline) {\n        await new Promise((r) => setTimeout(r, 250));\n        if (\n          document.querySelector(\n            `td[data-handler=\"selectDay\"][data-month=\"${targetMonth0}\"][data-year=\"${targetYear}\"] a[data-date=\"${targetDay}\"]`\n          )\n        ) {\n          break;\n        }\n      }\n      const titles = Array.from(document.querySelectorAll(\".ui-datepicker-month, .ui-datepicker-year\")).map((t) => t.textContent.trim());\n      navLog.push(`i=${i}: clicked, titles=${JSON.stringify(titles)}`);\n    }\n\n    if (!document.querySelector(`td[data-handler=\"selectDay\"][data-month=\"${targetMonth0}\"][data-year=\"${targetYear}\"] a[data-date=\"${targetDay}\"]`)) {\n      const widgetPresent = !!document.querySelector(\".ui-datepicker-next, td[data-handler=\\\"selectDay\\\"]\");\n      const anyDataMonth = document.querySelectorAll(\"[data-month]\").length;\n      throw new Error(\n        \"Step 1 (click): no element matched candidates DEBUG \" +\n          JSON.stringify({ iterations, navLog, widgetPresent, anyDataMonth, url: location.href, targetMonth0, targetYear, targetDay })\n      );\n    }\n\n    const el1 = findEl(\n      [\n        `xpath=//td[@data-handler=\"selectDay\" and @data-month=\"${targetMonth0}\" and @data-year=\"${targetYear}\"]/a[@data-date=\"${targetDay}\"]`,\n      ],\n      1,\n      \"click\"\n    );\n    el1.click();\n    await new Promise((r) => setTimeout(r, 1200));\n\n    // Step 2: select the first available time slot (the booking schema has no specific\n    // time-of-day field, so the recording's own choice -- the first offered slot -- is used).\n    // Real gap found 2026-09-24: clicking the wrapping <label> (a raw synthetic .click())\n    // did not reliably trigger the radio's own change handler -- confirmed the \"Add tickets\n    // to cart\" section never rendered its real content afterward (only an invisible,\n    // zero-size TEMPLATE row stayed in the DOM: class=\"abc-tariffoption-template\"). Clicking\n    // the radio <input> itself and explicitly dispatching change/input fixed it.\n    const el2 = findEl(['[name=\"slot\"]'], 2, \"click\");\n    el2.checked = true;\n    el2.click();\n    el2.dispatchEvent(new Event(\"change\", { bubbles: true }));\n    el2.dispatchEvent(new Event(\"input\", { bubbles: true }));\n\n    // Real gap found 2026-09-24 (midaticket.com): the \"Add tickets to cart\" section renders\n    // in an unstable, multi-phase way after selecting a time slot -- confirmed live: a check\n    // for \".tariff-option\" briefly found one, then found the container completely empty\n    // moments later, before it settled into its real, final content. A single short wait\n    // isn't reliable here; poll until the target row's title text actually appears and stop\n    // only once it does (bounded, so a genuinely missing row still fails reasonably fast).\n    const tariffDeadline = Date.now() + 6000;\n    while (Date.now() < tariffDeadline) {\n      const found = Array.from(document.querySelectorAll(\".abc-tariffpicker .tariff-option .title\")).some(\n        (el) => (el.textContent || \"\").trim() === \"Full price\"\n      );\n      if (found) break;\n      await new Promise((r) => setTimeout(r, 300));\n    }\n\n    // Step 3: add `totalPax` tickets of the \"Full price\" tariff row specifically (not\n    // \"Reduction\"/\"Free\"). The \"+\" control is a Font Awesome icon button identified by its\n    // stable data-dir=\"up\" attribute, scoped to the row whose .title text is \"Full price\".\n    //\n    // Real gap found 2026-10-07, confirmed live against a real booking (totalPax=4): this\n    // loop fired a click and then just waited a flat 700ms before the next one, with NO\n    // check that the click actually landed -- confirmed live, manually replaying the exact\n    // same clicks one at a time, that a click can silently fail to increment the row's own\n    // quantity (same class of transient-AJAX-update race already found and fixed for\n    // Prado's pax stepper). The real automated run of this exact script, on this exact\n    // booking, ended with an EMPTY cart (checkout page showed only a service fee, zero\n    // admission tickets) despite reporting PAYMENT_REQUIRED -- a false success. Read the\n    // row's own displayed quantity and poll/retry the click until it actually reflects the\n    // running target, instead of trusting a fixed wait.\n    function getFullPriceQty() {\n      const row = Array.from(document.querySelectorAll(\".abc-tariffpicker .tariff-option\")).find(\n        (r) => (r.querySelector(\".title\")?.textContent || \"\").trim() === \"Full price\"\n      );\n      const text = row?.querySelector(\"input, .qty, .quantity\")?.value ?? row?.querySelector(\".count, .value\")?.textContent;\n      return parseInt(text ?? \"0\", 10) || 0;\n    }\n    const totalPax = getByPath(booking, \"totalPax\") || 1;\n    for (let target = getFullPriceQty() + 1; target <= totalPax; target++) {\n      const clickDeadline = Date.now() + 8000;\n      while (getFullPriceQty() < target && Date.now() < clickDeadline) {\n        const el3 = findEl(\n          [\n            \"xpath=//div[contains(@class,\\\"abc-tariffpicker\\\")]//div[contains(@class,\\\"tariff-option\\\")][.//span[contains(@class,\\\"title\\\") and normalize-space(text())=\\\"Full price\\\"]]//button[@data-dir=\\\"up\\\"]\",\n          ],\n          3,\n          \"click\"\n        );\n        el3.click();\n        await new Promise((r) => setTimeout(r, 500));\n      }\n      if (getFullPriceQty() < target) {\n        throw new Error(\n          `Step 3 (click): no element matched candidates [\"Full price + button\"] DEBUG ` +\n            JSON.stringify({ target, qtyNow: getFullPriceQty() })\n        );\n      }\n    }\n\n    // Step 4: proceed from ticket selection to the checkout/guest-details page. Real gap\n    // found 2026-09-24: this click sometimes lands directly on /checkout/, and sometimes on\n    // an interim /cart/ review page first (confirmed live, both outcomes seen from the exact\n    // same starting state) -- the button re-uses the SAME id/class on that interim page too,\n    // so poll for the checkout form and, if a buy-button is still there instead, click it\n    // again, rather than assuming one click is always enough.\n    // Real gap found 2026-10-08 (RO team, live ticket: checkout with an empty Summary and \"The\n    // cart content is changed\"): after a \"+\" click the cart is updated asynchronously (~2s; the\n    // header total goes EUR 0.00 -> EUR 18.00) and \"Go to Payment\" carries class `disabled`\n    // until it lands. That control is an <a href=\"/checkout\">, so clicking it while \"disabled\"\n    // STILL navigates -- straight to a checkout page whose cart doesn't exist yet. Wait for the\n    // button to actually enable (and stay enabled) before clicking it.\n    const readyDeadline = Date.now() + 30000;\n    let stableSince = null;\n    while (Date.now() < readyDeadline) {\n      const b = document.querySelector(\"#buy-button.payment-button, a#buy-button\");\n      const ready = !!b && !b.classList.contains(\"disabled\") && getFullPriceQty() >= totalPax;\n      if (ready) {\n        stableSince = stableSince ?? Date.now();\n        if (Date.now() - stableSince >= 1000) break;\n      } else {\n        stableSince = null;\n      }\n      await sleep(250);\n    }\n    if (stableSince === null) {\n      throw new Error(\"The cart did not update after adding the tickets (\\\"Go to Payment\\\" stayed disabled)\");\n    }\n    const el4 = findEl([\"#buy-button.payment-button\", \"a#buy-button\"], 4, \"click\");\n    el4.click();\n    // Do NOT keep clicking while waiting for the navigation (see bridgeToCheckout()): give this\n    // click a long window to land before bridgeToCheckout() is allowed to click again.\n    const landDeadline = Date.now() + 40000;\n    while (Date.now() < landDeadline && !document.querySelector(\"#checkout_last_name, #checkout_first_name\")) await sleep(300);\n    await bridgeToCheckout();\n  }\n\n  async function runCheckoutFormSteps(booking) {\n    // A checkout page with an empty/changed cart must never be reported as success (RO team,\n    // 2026-10-08: the form was filled and the run looked fine, but the Summary was empty).\n    // Give the summary a moment to render, then require the booked tickets to be listed.\n    const totalPax = getByPath(booking, \"totalPax\") || 1;\n    const summaryDeadline = Date.now() + 10000;\n    let summaryQty = null;\n    while (Date.now() < summaryDeadline) {\n      summaryQty = Number(/Full price\\s*(\\d+)/i.exec(document.body.innerText)?.[1] ?? NaN);\n      if (summaryQty === totalPax) break;\n      await sleep(300);\n    }\n    if (/cart content is changed/i.test(document.body.innerText) || summaryQty !== totalPax) {\n      throw new Error(\n        `Checkout cart is wrong: expected ${totalPax} x Full price in the summary but found ${Number.isNaN(summaryQty) ? \"none\" : summaryQty}` +\n          (/cart content is changed/i.test(document.body.innerText) ? \" (\\\"The cart content is changed\\\")\" : \"\")\n      );\n    }\n\n    // Step 5: fill last name.\n    const el5 = findEl([\"#checkout_last_name\"], 5, \"fill\");\n    setNativeValue(el5, getByPath(booking, \"guestDetails.lastName\"));\n\n    // Step 6: fill first name.\n    const el6 = findEl([\"#checkout_first_name\"], 6, \"fill\");\n    setNativeValue(el6, getByPath(booking, \"guestDetails.firstName\"));\n\n    // Step 7: fill email.\n    const el7 = findEl([\"#checkout_email\"], 7, \"fill\");\n    setNativeValue(el7, getByPath(booking, \"guestDetails.email\"));\n\n    // Step 8: fill email confirmation.\n    const el8 = findEl([\"#checkout_email_confirm\"], 8, \"fill\");\n    setNativeValue(el8, getByPath(booking, \"guestDetails.email\"));\n\n    // Step 9: check ONLY the first (mandatory) consent checkbox. Per explicit vendor\n    // guidance, the second checkbox is not required to proceed.\n    const el9 = findEl([\"#midaabc-form-check-covid_rules\"], 9, \"check\");\n    if (!el9.checked) {\n      el9.click();\n    }\n  }\n\n  window.HeadoutAutomation = {\n    async run(booking, ctx) {\n      const readyDeadline = Date.now() + 15000;\n      while (document.readyState !== \"complete\" && Date.now() < readyDeadline) await sleep(200);\n      // A single clean pass through this flow (calendar navigation with settle-waits, time\n      // slot, pax stepper, checkout) genuinely takes several seconds -- a short retry budget\n      // sized for a quick form-fill would cut off a pass that's still correctly in progress.\n      const deadline = Date.now() + 20000;\n      while (true) {\n        try {\n          return await runSteps(booking, ctx);\n        } catch (e) {\n          const message = e && e.message ? e.message : String(e);\n          const isMissingElement = /^Step \\d+ \\(\\w+\\): no element matched candidates/.test(message);\n          if (!isMissingElement || Date.now() >= deadline) {\n            return { status: \"ERROR\", error: message };\n          }\n          await new Promise((r) => setTimeout(r, 200));\n        }\n      }\n    },\n  };\n})();\n"
};
